import { ipcMain } from 'electron'
import type { Database } from 'better-sqlite3-multiple-ciphers'
import { getDb } from '../db/schema'
import { searchCompanies, getCompanyProfile, getCHClient } from '../services/companies-house'
import { auditChanges, writeAudit, type Row } from '../access/audit'
import { clientById, UserFacingError, where, type Actor } from '../access/policy'
import { actor } from './session'

/** Applies Companies House dates to a client, recording only what changed, with its previous value. */
function applyProfile(db: Database, who: Actor | null, clientId: number, set: Record<string, string | null>, action: string): boolean {
  return db.transaction((): boolean => {
    const before = db.prepare('SELECT * FROM clients WHERE id = ?').get(clientId) as Row | undefined
    if (!before) return false
    const cols = Object.keys(set).filter((c) => (set[c] ?? null) !== (before[c] ?? null))
    if (!cols.length) return false
    db.prepare(`UPDATE clients SET ${cols.map((c) => `${c} = ?`).join(', ')}, updated_at = datetime('now') WHERE id = ?`).run(...cols.map((c) => set[c]), clientId)
    const after = db.prepare('SELECT * FROM clients WHERE id = ?').get(clientId) as Row
    const diff = auditChanges('clients', before, after, ['ref', 'client_name'])
    if (diff) writeAudit(db, who, action, 'clients', clientId, diff.before, diff.after)
    return true
  })()
}

