// Staff refresh their own clients; partners and managers refresh every client with a company number.
ipcMain.handle('ch:bg-sync-clients', async () => {
  try {
    const db = getDb()
    const me = actor()
    const mine = me.role === 'staff' ? { sql: 'assigned_to = ?', params: [me.name] } : { sql: '', params: [] }
    const w = where(mine, { sql: "reg_no IS NOT NULL AND reg_no != ''", params: [] })
    const clients = db.prepare(`SELECT id, reg_no FROM clients${w.sql}`).all(...w.params) as { id: number; reg_no: string }[]
    let synced = 0

    for (const client of clients) {
      try {
        const company = await getCompanyProfile(client.reg_no)
        applyProfile(db, me, client.id, {
          inc_date: company.date_of_creation ?? null,
          accounts_due: company.accounts?.next_due || null,
          conf_stmt_due: company.confirmation_statement?.next_due || null
        }, 'Updated client from Companies House')
        synced++
        // Avoid aggressive rate limiting during batch sync
        await new Promise(r => setTimeout(r, 100))
      } catch (itemErr) {
        console.error(`[Sync] Failed for client ${client.id}:`, itemErr)
      }
    }
    return { success: true, synced, total: clients.length }
  } catch (err) {
    return { success: false, synced: 0, total: 0, error: err instanceof UserFacingError ? err.message : String(err) }
  }
})

